import (
	"strings"
	"testing"
)

func TestNetStaysWithinGross(t *testing.T) {
	for gross := 0; gross <= 1000; gross++ {
		if n := Net(gross); n < 0 || n > gross {
			t.Fatalf("Net(%d) = %d", gross, n)
		}
	}
}

func TestLabelNamesTheItem(t *testing.T) {
	if !strings.Contains(Label("lamp"), "lamp") {
		t.Fatal(Label("lamp"))
	}
}

package gate

func Label(name string) string {
	return "item: " + name
}

package gate

func Net(gross int) int {
	return gross - Discount(gross)
}

func Discount(gross int) int {
	return gross / 10
}

